# the fix lane after the lens of 2026-10-15 (#43, lane fix-anchor-cite) held these (site, the citation as written) by one
# reason, never a row; read by `--propose` and counted by the leg as HELD_PASS is
HELD_DISCRETION_WHY = "held under the node team's discretion request"
# WITHHELD: d8-node-team-discretion held citation pairs.
HELD_DISCRETION = set()


def host_path(p):
    """A pins value `$NAME` names a path the owner's host file tools/host_private.sh holds (withheld from the
    public edition, #46); unresolved, the name stays and the clone reads as absent. Any other value is a path."""
    m = re.fullmatch(r"\$([A-Z][A-Z0-9_]*)", p.strip())
    if not m:
        return os.path.expanduser(p)
    try:
        src = open(os.path.join(ROOT, "tools", "host_private.sh"), encoding="utf-8").read()
    except OSError:
        return p
    v = re.search(r'^' + m.group(1) + r'="([^"]*)"$', src, re.M)
    return v.group(1).replace("$HOME", os.path.expanduser("~")) if v else p


def pins():
    """docs/PROVENANCE.md §1a, the fenced `pins` block (the same reader as tools/check_pins.py)."""
    text = open(os.path.join(ROOT, "docs", "PROVENANCE.md"), encoding="utf-8").read()
    m = re.search(r"```pins\n(.*?)```", text, re.S)
    if not m:
        sys.exit("cite_check: docs/PROVENANCE.md has no ```pins block")
    out = {}
    for line in m.group(1).splitlines():
        line = line.split("#", 1)[0].strip()
        if "=" in line:
            k, v = line.split("=", 1)
            out[k.strip()] = v.strip()
    return out


def git(clone, *args, binary=False):
    r = subprocess.run(["git", "-C", clone] + list(args), capture_output=True)
    if r.returncode != 0:
        return None
    return r.stdout if binary else r.stdout.decode("utf-8", "replace")


class Sources:
    """The pinned repositories: their file lists and file texts at the pin, read once."""

    def __init__(self, pinmap):
        self.repo = OrderedDict()   # name -> (clone, commit) for the clones present
        self.absent = OrderedDict()  # name -> why
        self.files = {}
        self.texts = {}
        for name, (ck, mk) in REPOS.items():
            clone = host_path(pinmap.get(ck, "")) if pinmap.get(ck) else ""
            commit = pinmap.get(mk, "")
            if not clone or not commit:
                self.absent[name] = f"no {ck}/{mk} in the pins block"
                continue
            if not os.path.isdir(clone):
                self.absent[name] = f"clone absent: {pinmap.get(ck)}"
                continue
            full = git(clone, "rev-parse", "--verify", "--quiet", commit + "^{commit}")
            if not full:
                self.absent[name] = f"{commit} not in {pinmap.get(ck)}"
                continue
            self.repo[name] = (clone, full.strip())
            listing = git(clone, "ls-tree", "-r", "--name-only", full.strip()) or ""
            self.files[name] = listing.split("\n")

    def candidates(self, path):
        """Every (repo, fullpath) whose path is the cited one or ends with it."""
        out = []
        for name, files in self.files.items():
            for f in files:
                if f == path or f.endswith("/" + path):
                    out.append((name, f))
        return out

    def lines(self, name, path):
        key = (name, path)
        if key not in self.texts:
            clone, commit = self.repo[name]
            t = git(clone, "show", f"{commit}:{path}")
            self.texts[key] = None if t is None else t.split("\n")
        return self.texts[key]


def scan_sites(excluded=None):
    """Live citation sites only; append excluded history names without opening them."""
    found = []
    for top, ext in SCAN:
        base = os.path.join(ROOT, top)
        for dirpath, dirnames, filenames in os.walk(base):
            dirnames[:] = sorted(d for d in dirnames if d not in (".lake", "build", ".git"))
            for fn in sorted(filenames):
                if not fn.endswith(ext):
                    continue
                full = os.path.join(dirpath, fn)
                site = os.path.relpath(full, ROOT)
                # History may hold owner-closed evidence. Name it, but never open it.
                if site.startswith(HISTORY_PREFIX):
                    if excluded is not None:
                        excluded.append(site)
                    continue
                text = open(full, encoding="utf-8", errors="replace").read()
                for m in CITE.finditer(text):
                    path = m.group(1)
                    first = int(m.group(2))
                    last = int(m.group(3)) if m.group(3) else first
                    ranges = [(first, last)]
                    for e in EXTRA.finditer(m.group(4) or ""):
                        a = int(e.group(1))
                        ranges.append((a, int(e.group(2)) if e.group(2) else a))
                    lineno = text.count("\n", 0, m.start()) + 1
                    found.append({"site": site, "at": lineno, "cite": m.group(0), "path": path, "ranges": ranges,
                                  "start": m.start(), "text": text})
    return found


def context_repos(text, start):
    """The sources a page's sentence names before the citation (within its paragraph), nearest first."""
    para_start = text.rfind("\n\n", 0, start)
    window = text[max(para_start, start - 600, 0):start]
    found = []
    for name, words in CONTEXT.items():
        at = max(window.rfind(w) for w in words)
        if at >= 0:
            found.append((at, name))
    return [name for _, name in sorted(found, reverse=True)]


_OWN = None


def own_files():
    """This repository's tracked files (a citation of one of them by its bare name is `self`)."""
    global _OWN
    if _OWN is None:
        _OWN = (git(ROOT, "ls-files") or "").split("\n")
    return _OWN


def resolve(src, c):
    """(kind, repo, fullpath): kind is `pinned`, `self`, `history`, `unresolved`, `ambiguous`, `absent`."""
    if c["site"].startswith(HISTORY_PREFIX):
        return ("history", None, None)
    path = c["path"]
    if path.startswith(SELF_TOP) or path.endswith(".lean"):
        return ("self", None, None)
    only = None
    for pre, name in CLONE_PREFIX.items():
        if path.startswith(pre):
            path, only = path[len(pre):], name
            break
    cands = src.candidates(path)
    if only:
        cands = [(r, f) for r, f in cands if r == only]
    if not cands:
        if any(f == path or f.endswith("/" + path) for f in own_files()):
            return ("self", None, None)
        if src.absent:
            return ("absent", None, None)
        return ("unresolved", None, None)
    named = context_repos(c["text"], c["start"])
    near = c["text"][max(0, c["start"] - 40):c["start"]]
    for name, words in CONTEXT.items():
        if name not in REPOS and any(w in near for w in words):
            return ("unpinned", None, None)   # the citation is qualified by a source §1a does not pin (CONTEXT's tail)
    holders = {r for r, _ in cands}
    if not only and not any(n in holders for n in named) and any(
            f == path or f.endswith("/" + path) for f in own_files()):
        # a bare name this repository also tracks (`lakefile.toml:11` beside `rev = …`, `PROVENANCE.md:14`, a shim's
        # `main.go`) cites our own file when the paragraph names no pinned source that holds it (until 2026-09-27 the
        # one pinned holder won: two such citations were anchored on a blank line of the predecessor Lean tree's lakefile)
        return ("self", None, None)
    if len(holders) > 1:
        # two sources hold the path: the sentence's own naming decides (the nearest named source that holds it); a
        # sentence that names none of them cites the reference (CLAUDE.md rule 2: the bitcoin-sv source at the pin)
        want = next((n for n in named if n in holders), "bitcoin-sv")
        cands = [(r, f) for r, f in cands if r == want]
        if not cands:
            return ("ambiguous", None, None)
    exact = [(r, f) for r, f in cands if f == path]
    if len(exact) == 1:
        cands = exact
    if len({f for _, f in cands}) > 1:
        # one source, two files ending with the path: the one outside the auxiliary trees, when exactly one is
        main = [(r, f) for r, f in cands if not set(f.split("/")[:-1]) & set(AUX_DIRS)]
        if len(main) != 1:
            return ("ambiguous", None, None)
        cands = main
    r, f = cands[0]
    end = c["start"] + len(c["cite"])
    if BRANCH_AFTER.search(c["text"][end:end + 40]):
        return ("other-version", r, f)
    vk = VERSION_KEYS.get(r)
    if vk:
        pinned_v = PINS.get(vk, "").lstrip("v")
        vb = VERSION_BEFORE.search(c["text"][max(0, c["start"] - 40):c["start"]])
        va = VERSION_AFTER.search(c["text"][end:end + 120])
        for m in (vb, va):
            if m and m.group(1) != pinned_v:
                return ("other-version", r, f)
    return ("pinned", r, f)


# ---------------------------------------------------------------------------------------------------------------
# anchors

IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]{3,}")
COMMON = {"this", "that", "with", "from", "when", "true", "false", "none", "line", "lines", "file", "note", "the",
          "and", "which", "where", "each", "every", "else", "then", "since", "flag", "flags", "word", "words", "height",
          "error", "errors", "script", "scripts", "input", "inputs", "output", "outputs", "test", "tests", "value",
          "values", "type", "return", "returns", "call", "calls", "site", "sites", "read", "reads", "case", "cases"}


def symbol_like(tok):
    """An identifier, never a word: CamelCase, SCREAMING_CASE, snake_case or with a digit (`GetBlockScriptFlags`,
    `SCRIPT_VERIFY_LOW_S`, `make_verify_script_params`, `OP_2DUP`); a plain lower-case word (`consensus`) never anchors."""
    return bool(re.search(r"[A-Z]", tok[1:]) or "_" in tok or re.search(r"\d", tok))


def neighbour_symbols(c):
    """The symbols of the citation's own sentence: the backticked ones first, then the bare ones, nearest first."""
    text, start = c["text"], c["start"]
    left = max(text.rfind("\n", 0, start), text.rfind(". ", 0, start), start - 240)
    right_nl = text.find("\n", start)
    right = min(right_nl if right_nl >= 0 else len(text), start + len(c["cite"]) + 160)
    span = text[left:right]
    rel = start - left
    stem = c["path"].split("/")[-1].split(".")[0]
    out = []
    for m in re.finditer(r"`([^`\n]{2,120})`", span):
        for t in IDENT.finditer(m.group(1)):
            tok = t.group(0)
            if tok != stem and tok.lower() not in COMMON and symbol_like(tok):
                out.append((abs(m.start() + t.start() - rel), tok))
    for t in IDENT.finditer(span):
        tok = t.group(0)
        if tok != stem and tok.lower() not in COMMON and symbol_like(tok) and len(tok) >= 6:
            out.append((abs(t.start() - rel) + 1000, tok))  # the bare identifiers after the backticked ones
    seen, ordered = set(), []
    for _, tok in sorted(out):
        if tok not in seen:
            seen.add(tok)
            ordered.append(tok)
    return ordered


def norm(s):
    return " ".join(s.split())


def propose_row(src, c, repo, fullpath, first, last, findings):
    lines = src.lines(repo, fullpath)
    if lines is None or first < 1 or last < first or last > len(lines):
        return None
    body = "\n".join(lines[first - 1:last])
    syms = neighbour_symbols(c)
    for tok in syms:
        if tok in body:
            return {"kind": "sym", "anchor": tok, "anchor_end": ""}
    # a neighbour symbol that is NOT in the cited lines but IS within six lines of them: a near-miss, reported
    lo, hi = max(1, first - 6), min(len(lines), last + 6)
    near = "\n".join(lines[lo - 1:hi])
    for tok in syms[:3]:
        if tok in near:
            where = [i for i in range(lo, hi + 1) if tok in lines[i - 1]]
            findings.append(f"near-miss: {c['site']}:{c['at']} cites {c['cite']} beside `{tok}`, which is not in "
                            f"{fullpath}:{first}–{last} at the pin but is at line(s) {', '.join(map(str, where))}")
            break
    return {"kind": "text", "anchor": norm(lines[first - 1]), "anchor_end": norm(lines[last - 1]) if last != first else ""}


def check_row(src, row):
    """None when the anchor holds at the pin, else the reason."""
    repo = row["repo"]
    lines = src.lines(repo, row["path"])
    if lines is None:
        return f"{row['path']} is not in {repo} at the pin"
    first, last = row["first"], row["last"]
    if last > len(lines):
        return f"{row['path']} has {len(lines)} lines at the pin, the citation reaches {last}"
    if row["kind"] == "sym":
        if row["anchor"] in "\n".join(lines[first - 1:last]):
            return None
        hits = [i + 1 for i, l in enumerate(lines) if row["anchor"] in l]
        return f"`{row['anchor']}` is not in {row['path']}:{first}–{last} at the pin" + (
            f" (it is at {', '.join(map(str, hits[:6]))})" if hits else " (nor anywhere in the file)")
    if norm(lines[first - 1]) != row["anchor"]:
        return f"{row['path']}:{first} at the pin is not the anchored text"
    if row["anchor_end"] and norm(lines[last - 1]) != row["anchor_end"]:
        return f"{row['path']}:{last} at the pin is not the anchored text"
    return None


# ---------------------------------------------------------------------------------------------------------------
# the table, kept in this file between the markers (JSON, one row per line; `--propose --write` rewrites it)

# the markers are built, never written whole in the code, so the only lines equal to them are the table's own
BEGIN_MARK = "# --- ANCHORS " + "BEGIN (generated by --propose --write; a row may be edited by hand) ---"
END_MARK = "# --- ANCHORS " + "END ---"


def table_span(text):
    """The table's offsets: the marker LINES (a line equal to the marker), the last pair in the file."""
    a = text.rindex("\n" + BEGIN_MARK + "\n") + 1
    b = text.rindex("\n" + END_MARK)
    if b < a:
        sys.exit("cite_check: the table's markers are out of order")
    return a, b + 1


def load_rows():
    text = open(SELF, encoding="utf-8").read()
    a, b = table_span(text)
    rows = []
    for line in text[a:b].split("\n")[1:]:
        line = line.strip()
        if line.startswith("# {"):
            rows.append(json.loads(line[2:]))
    return rows


def write_rows(rows):
    text = open(SELF, encoding="utf-8").read()
    a, b = table_span(text)
    body = "\n".join("# " + json.dumps(r, ensure_ascii=False, separators=(", ", ": ")) for r in rows)
    new = text[:a] + BEGIN_MARK + "\n" + body + ("\n" if body else "") + text[b:]
    open(SELF, "w", encoding="utf-8").write(new)


def key(site, cite, first, last):
    return (site, cite, first, last)


PINS = {}


def main():
    args = sys.argv[1:]
    pinmap = pins()
    repins = [args[i + 1] for i, a in enumerate(args) if a == "--repin" and i + 1 < len(args)]
    for r in repins:
        k, _, v = r.partition("=")
        if k not in pinmap or not v:
            sys.exit(f"cite_check: --repin {r}: not a key of the pins block, or no value")
        pinmap[k] = v
    if repins and "--propose" in args:
        sys.exit("cite_check: --repin never writes the table")
    PINS.update(pinmap)
    src = Sources(pinmap)
    require = os.environ.get("CITE_CHECK_REQUIRE_CLONES") == "1"
    rows = load_rows()
    by_key = {key(r["site"], r["cite"], r["first"], r["last"]): r for r in rows}
    excluded = []
    cites = scan_sites(excluded)
    for site in excluded:
        print(f"cite_check: [LIT] {site}: closed to model turns, not opened")
    history_rows = [r for r in rows if r["site"].startswith(HISTORY_PREFIX)]
    history_keys = {key(r["site"], r["cite"], r["first"], r["last"]) for r in history_rows}
    print(f"cite_check: excluded files [D] {len(excluded)}; closed to model turns, not opened; "
          f"excluded anchor rows [D] {len(history_rows)} (retained, not scanned)")
    counts = Counter()       # per (occurrence, range): every citation found lands in exactly one class
    moved, findings, listing, proposed = [], [], [], []
    used, checked, proposed_keys, held_hit = set(), {}, set(), set()
    skipped = Counter()
    n_ranges = 0
    for c in cites:
        kind, repo, fullpath = resolve(src, c)
        for first, last in c["ranges"]:
            n_ranges += 1
            k = key(c["site"], c["cite"], first, last)
            row = by_key.get(k)
            where = f"{c['site']}:{c['at']} {c['cite']}"
            if row is not None and row["repo"] not in src.repo:
                used.add(k)
                counts["skipped"] += 1
                skipped[row["repo"]] += 1
                listing.append(f"SKIP       {where} -> {row['repo']} ({src.absent.get(row['repo'], 'absent')})")
                continue
            if kind != "pinned":
                counts[kind] += 1
                listing.append(f"{kind:<10} {where}")
                continue
            if row is not None:
                used.add(k)
                if k not in checked:
                    checked[k] = check_row(src, row)
                why = checked[k]
                if why:
                    counts["moved"] += 1
                    moved.append(f"{where}: {why}")
                    listing.append(f"MOVED      {where}: {why}")
                else:
                    counts["anchored"] += 1
                    listing.append(f"ok         {where} -> {row['repo']}:{row['path']}:{first}–{last} [{row['kind']}: {row['anchor'][:60]}]")
                continue
            lines = src.lines(repo, fullpath)
            if lines is None or first < 1 or last < first or last > len(lines):
                counts["beyond-eof"] += 1
                n = "?" if lines is None else len(lines)
                findings.append(f"beyond-eof: {where}: {repo}:{fullpath} has {n} lines at the pin")
                listing.append(f"beyond-eof {where} -> {repo}:{fullpath} ({n} lines)")
                continue
            counts["unanchored"] += 1
            listing.append(f"unanchored {where} -> {repo}:{fullpath}:{first}–{last}")
            if "--propose" in args and k not in proposed_keys:
                proposed_keys.add(k)
                held = HELD.get((c["site"], c["cite"])) or (
                    HELD_PASS_WHY if (c["site"], c["cite"]) in HELD_PASS else None) or (
                    HELD_DISCRETION_WHY if (c["site"], c["cite"]) in HELD_DISCRETION else None)
                if held:
                    held_hit.add((c["site"], c["cite"]))
                    findings.append(f"held: {where}: no row is proposed ({held})")
                p = None if held else propose_row(src, c, repo, fullpath, first, last, findings)
                if p:
                    proposed.append(dict(site=c["site"], cite=c["cite"], first=first, last=last, repo=repo,
                                         commit=src.repo[repo][1][:12], path=fullpath, **p))
    seen = used | proposed_keys | history_keys
    orphans = [r for r in rows if key(r["site"], r["cite"], r["first"], r["last"]) not in seen]
    counts["orphan"] = len(orphans)
    if require and src.absent:
        for name, why in src.absent.items():
            moved.append(f"CITE_CHECK_REQUIRE_CLONES=1 and {name} is absent ({why})")

    if "--list" in args:
        print("\n".join(listing))
    if "--propose" in args:
        for (site, cite), why in (list(HELD.items()) + [(k, HELD_PASS_WHY) for k in sorted(HELD_PASS)]
                           + [(k, HELD_DISCRETION_WHY) for k in sorted(HELD_DISCRETION)]):
            if not site.startswith(HISTORY_PREFIX) and (site, cite) not in held_hit:
                findings.append(f"held entry spent: {site} carries no unanchored {cite} any more; remove it from HELD "
                                f"({why})")
        # a proposal runs the near-miss scan over every pinned citation, the anchored ones included
        for c in cites:
            kind, repo, fullpath = resolve(src, c)
            if kind != "pinned":
                continue
            for first, last in c["ranges"]:
                if key(c["site"], c["cite"], first, last) in used:
                    propose_row(src, c, repo, fullpath, first, last, findings)
        kept = [r for r in rows if key(r["site"], r["cite"], r["first"], r["last"]) in used | history_keys]
        new_rows = sorted(kept + proposed, key=lambda r: (r["site"], r["cite"], r["first"], r["last"]))
        print(f"cite_check --propose: {len(proposed)} rows proposed ({Counter(p['kind'] for p in proposed)}), "
              f"{len(orphans)} orphan rows dropped, {len(new_rows)} rows after")
        for f in sorted(set(findings)):
            print("  " + f)
        if "--write" in args:
            write_rows(new_rows)
            print(f"cite_check --propose --write: the table in {os.path.relpath(SELF, ROOT)} rewritten ({len(new_rows)} rows)")
        return 0

    if repins:
        print(f"cite_check --repin {' '.join(repins)} (in memory; the pins block is unchanged):")
    for m in moved:
        print("  MOVED " + m)
    skip_line = "; ".join(f"{n} SKIPPED BY NAME ({src.absent.get(n)}), {k} rows" for n, k in skipped.items())
    absent_line = "; ".join(f"{n}: {why}" for n, why in src.absent.items())
    print(f"cite_check: {n_ranges} citations found in lean/ and docs/ ({len(cites)} `file:line` shapes, a `/`-list counted per line); anchored and holding at the pin {counts['anchored']}, "
          f"MOVED {counts['moved']}; not anchored (reported, never RED): unanchored {counts['unanchored']}, "
          f"beyond-eof {counts['beyond-eof']}, unresolved {counts['unresolved']}, ambiguous {counts['ambiguous']}, "
          f"unpinned {counts['unpinned']}, other-version {counts['other-version']}, self {counts['self']}, "
          f"history {counts['history']}, absent {counts['absent']}, orphan rows {counts['orphan']}; "
          f"skipped {counts['skipped']}" + (f" ({skip_line})" if skip_line else "") +
          (f"; sources absent here: {absent_line}" if absent_line else ""))
    if moved:
        print("cite_check: RED (an anchored citation's anchor is no longer where the citation says, at the pin)")
        return 1
    print("cite_check: GREEN (every checked active anchor holds at the pin; closed history is not checked)")
    return 0


if __name__ == "__main__":
    sys.exit(main())

